from taf.fdsw.rc.interfaces.FDSW21D.fdsw import FDSW21D
from taf.fdsw.rc.interfaces.FDSW22A.autoconnection import AutoConfiguration22A
from taf.fdsw.rc.interfaces.FDSW22A.swm import SoftwareManagement22A


class FDSW22A(FDSW21D):
    VERSION_NAME = 'FDSW22A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure):
        super(FDSW22A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)

        self.autoconnection = AutoConfiguration22A(client=self._client)
        self.swm = SoftwareManagement22A(client=self._client)
